#!/usr/bin/perl -w
use Cwd;
$wd=cwd;
print "Preparing input files\n";
$name="ala_tri";
$incr=3;
$force=200.0;
&prepare_input();
exit(0);
sub prepare_input() {
 $dihed=0;
 while ($dihed <= 90) { 
 if ($dihed != 60) {
 #skip 60 degrees since we already ran it
 print "Processing dihedral: $dihed\n";
 &write_mdin0();
 &write_mdin1();
 &write_mdin2();
 &write_disang();
 &write_batchfile();
 system("qsub run.pbs.$dihed");
 }
 $dihed += $incr;
 }
}
sub write_mdin0 {
 open MDINFILE,'>', "mdin_min.$dihed";
 print MDINFILE <<EOF;
2000 step minimization for $dihed deg
 &cntrl
 imin = 1, 
 maxcyc=2000, ncyc = 500,
 ntpr = 100, ntwr = 1000,
 ntf = 1, ntc = 1, cut = 8.0,
 ntb = 1, ntp = 0,
 nmropt = 1,
 &end
 &wt 
 type='END',
 &end
DISANG=disang.$dihed
EOF
 close MDINFILE;
}
sub write_mdin1 {
 open MDINFILE,'>', "mdin_equi.$dihed";
 print MDINFILE <<EOF;
50 ps NPT equilibration for $dihed deg
 &cntrl
 imin = 0, ntx = 1, irest = 0,
 ntpr = 5000, ntwr = 50000, ntwx = 0,
 ntf = 2, ntc = 2, cut = 8.0,
 ntb = 2, nstlim = 50000, dt = 0.001,
 tempi=0.0, temp0 = 300, ntt = 3,
 gamma_ln = 1.0,
 ntp = 1, pres0 = 1.0, taup = 5.0,
 nmropt = 1, ioutfm=1,
 &end
 &wt 
 type='END',
 &end
DISANG=disang.$dihed
