}
sub write_mdin2 {
 open MDINFILE,'>', "mdin_prod.$dihed";
 print MDINFILE <<EOF;
100 ps NPT production for $dihed deg
 &cntrl
 imin = 0, ntx = 5, irest = 1,
 ntpr = 10000, ntwr = 0, ntwx = 10000,
 ntf = 2, ntc = 2, cut = 8.0,
 ntb = 2, nstlim = 100000, dt = 0.001,
 temp0 = 300, ntt = 3,
 gamma_ln = 1.0,
 ntp = 1, pres0 = 1.0, taup = 5.0,
 nmropt = 1, ioutfm=1,
 &end
 &wt
 type='DUMPFREQ', istep1=50,
 &end
 &wt 
 type='END',
 &end
DISANG=disang.$dihed
DUMPAVE=dihedral_${dihed}.dat
EOF
 close MDINFILE;
}
sub write_disang {
 $left = sprintf "%4.1f", $dihed - 180;
 $min = sprintf "%4.1f", $dihed;
 $right = sprintf "%4.1f", $dihed + 180;
 open DISANG,'>', "disang.$dihed";
 print DISANG <<;
Harmonic restraints for $dihed deg
 &rst
 iat=9,15,17,19,
 r1=$left, r2=$min, r3=$min, r4=$right,
 rk2=${force}, rk3=${force},
 &end
EOF
 close DISANG;
}
sub write_batchfile {
 open BATCHFILE, '>', "run.pbs.$dihed";
 print BATCHFILE <<EOF;
#PBS -l nodes=1:ppn=2
#PBS -l walltime=1:00:

n, r4=$right,
 rk2=${force}, rk3=${force},
 &end
EOF
 close DISANG;
}
sub write_batchfile {
 open BATCHFILE, '>', "run.pbs.$dihed";
 print BATCHFILE <<EOF;
#PBS -l nodes=1:ppn=2
#PBS -l walltime=1:00:00
#PBS -N run_$dihed
cd $wd
mpirun -np 2 -machinefile \$PBS_NODEFILE pmemd.MPI -O \\
-i mdin_min.$dihed -p ${name}.prmtop -c ala_tri_prod_60.rst -r ${name}_min_${dihed}.rst -o ${name}_min_${dihed}.out 
mpirun -np 2 -machinefile \$PBS_NODEFILE pmemd.MPI -O \\
-i mdin_equi.$dihed -p ${name}.prmtop -c ${name}_min_${dihed}.rst -r ${name}_equil_${dihed}.rst -o ${name}_equil_${dihed}.out 
mpirun -np 2 -machinefile \$PBS_NODEFILE pmemd.MPI -O \\
-i mdin_prod.$dihed -p ${name}.prmtop -c ${name}_equil_${dihed}.rst -r ${name}_prod_${dihed}.rst -o ${name}_prod_${dihed}.out -x ${name}_prod_${dihed}.mdcrd
EOF
 print BATCHFILE "\necho \"Execution finished\"\n";
 close BATCHFILE;
}

Now that we have the necessary starting structures for all the calculations we
can write a script to generate all the input files for us, excluding 120 and 60
degrees since we have already run those. The perl scripts below are
ones that I wrote to generate all the input files as well as job submission
scripts for running on the Teragrid IA64 cluster at the San Diego Supercomputer
Center. You will likely need to modify this for your own system. Since each node
of the SDSC cluster has 2 processors I will run each job using pmemd.MPI across
2 processors.
The scripts are essentially identical, differing only in the range of angles
they calculate. prepare_runs_0-90.perl runs all of the runs from 0 degrees to 90 degrees using the ala_tri_prod_60.rst
as the starting structure. prepare_runs_93-147.perl runs 93 degrees to 147 degrees using the
ala_tri_prod_120.rst as the starting structure while prepare_runs_150-180.perl runs 150
to 180 degrees using the 03_equil.rst (180 deg) as the starting structure. The
example for 0 to 90 degrees is shown below:
